// Generate the duplicate-contact-name fixture (PRISTINE build only — see notes).
// One MCP client per identity, each with its own lease token, so no rebinding.
// Usage: node test/tmp-gen-dup-fixture.mjs <outDir>
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { mkdtempSync, rmSync, copyFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const CLI = join(HERE, '..', 'dist', 'cli.js');
const BROKER = join(HERE, '..', '..', '..', 'scripts', 'dev-broker.mjs');
const outDir = resolve(process.argv[2] ?? '.');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const freePort = () => new Promise((res, rej) => { const s = createServer(); s.listen(0, () => { const p = s.address().port; s.close(() => res(p)); }); s.on('error', rej); });
const txt = (r) => (Array.isArray(r.content) ? r.content : []).map((c) => (typeof c.text === 'string' ? c.text : '')).join('\n');
const withTimeout = (p, ms, what) => Promise.race([p, sleep(ms).then(() => { throw new Error(`${what} timed out after ${ms}ms`); })]);

const dir = mkdtempSync(join(tmpdir(), 'a2a-dupfix-'));
const BPORT = await freePort();
const broker = spawn('node', [BROKER, '--host', '127.0.0.1', '--port', String(BPORT), '--test_mode'], { stdio: 'ignore' });
await sleep(2000);
const PORT = await freePort();
const daemon = spawn('node', [CLI, 'serve'], {
  env: { ...process.env, OURS_TRANSPORT: 'http', OURS_PORT: String(PORT), OURS_STATE_DIR: dir, OURS_BROKER_URL: `ws://127.0.0.1:${BPORT}`, OURS_API_VISIBILITY: 'open' },
  stdio: 'ignore',
});

const clients = [];
async function mkClient(tag) {
  const transport = new StreamableHTTPClientTransport(new URL(`http://127.0.0.1:${PORT}/mcp`), {
    requestInit: { headers: { 'x-ours-lease-token': `fixture-${tag}-${PORT}`, 'x-ours-client-pid': String(process.pid) } },
  });
  const client = new Client({ name: `dupfix-${tag}`, version: '0.0.0' });
  await client.connect(transport);
  clients.push({ client, transport });
  return async (name, args = {}) => {
    const r = await withTimeout(client.callTool({ name, arguments: args }), 30_000, `${tag}:${name}`);
    const t = txt(r);
    console.log(`--- [${tag}] ${name}: ${t.split('\n')[0]}`);
    if (r.isError) throw new Error(`[${tag}] ${name} failed: ${t}`);
    return t;
  };
}

try {
  for (let i = 0; i < 120; i++) { try { if ((await fetch(`http://127.0.0.1:${PORT}/version`)).ok) break; } catch {} await sleep(250); }

  const bk = await mkClient('bk');
  const p1 = await mkClient('p1');
  const p2 = await mkClient('p2');

  await bk('create_identity', { name: 'BookKeeper', expose_local: false });
  await p1('create_identity', { name: 'PeerOne', expose_local: false });
  await p2('create_identity', { name: 'PeerTwo', expose_local: false });

  const blobOf = (invText) => {
    const m = invText.match(/:\s*\n\n([^\s]+)\s*$/);
    if (!m) throw new Error(`could not extract invite blob from:\n${invText}`);
    return m[1];
  };

  const inv1 = blobOf(await bk('generate_invite', { name: 'Twin' }));
  await p1('add_contact', { invite: inv1, name: 'BookKeeper' });
  await sleep(5000);
  const inv2 = blobOf(await bk('generate_invite', { name: 'Twin' }));
  await p2('add_contact', { invite: inv2, name: 'BookKeeper' });
  await sleep(5000);

  const contacts = await bk('list_contacts');
  console.log(contacts);
  const cids = [...contacts.matchAll(/Twin — ([0-9A-F]{64})/g)].map((m) => m[1]);
  if (cids.length !== 2) throw new Error(`expected two "Twin" contacts, got ${cids.length}:\n${contacts}`);

  for (const { client, transport } of clients) { try { await transport.terminateSession(); await client.close(); } catch {} }
  daemon.kill('SIGTERM');
  await sleep(2000);

  copyFileSync(join(dir, 'BookKeeper', 'state_data.bin'), join(outDir, 'dup-contacts-state.bin'));
  copyFileSync(join(dir, 'BookKeeper', 'identity.key'), join(outDir, 'dup-contacts-identity.key'));
  writeFileSync(join(outDir, 'dup-contacts-meta.json'), JSON.stringify({
    note: 'BookKeeper holds two contacts both named "Twin" — captured from the pre-uniqueness build (the fixed build cannot produce this state). Generated by gen-dup-fixture.mjs against the pristine unit at ours-mcp 849a355 / core edbb11ad.',
    twin_cids: cids,
  }, null, 2));
  console.log(`FIXTURE OK: twin cids ${cids.join(', ')}`);
  process.exit(0);
} catch (err) {
  console.error('FIXTURE GENERATION FAILED:', err);
  process.exit(1);
} finally {
  daemon.kill('SIGTERM');
  broker.kill('SIGTERM');
  rmSync(dir, { recursive: true, force: true });
}
